from typing import Callable, Any
import log

class PluginEvent[*Args]:
    all_events: "list[PluginEvent]" = []

    def __init__(self) -> None:
        self.bound: list[Callable[[*Args], Any]] = []
        PluginEvent.all_events.append(self)

    def bind(self, func: Callable[[*Args], Any]):
        "Alway unbind the event when not listening"
        self.bound.append(func)
        return func

    def call(self, args: tuple[*Args] = ()):
        for func in self.bound:
            func(*args)

    def unbind(self, func: Callable[[*Args], Any]):
        "You can only unbind bound functions"
        self.bound.remove(func)
        return func

    def __is_empty__(self):
        return len(self.bound) == 0

    @classmethod
    def __check_empty__(cls):
        for p in cls.all_events:
            if not p.__is_empty__():
                raise log.LiminalClientException(
                    "PluginEvent not unbound",
                    1,
                    "It seems not all PluginEvents have been fully unbound.",
                    "PluginEvent bound functions: %s"%(",".join(map(lambda x:str(x),p.bound))),
                    possible_causes=["Plugins not unbinding PluginEvents"],
                )  # ("failed empty check at",p,"please make sure this event is unbound before checked")
